:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --accent: #ff6b6b;
  --accent-hover: #ff8787;
  --muted: #a0a0b8;
  --focus: #ffd93d;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.app {
  text-align: center;
  width: 100%;
  max-width: 400px;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 24px;
  letter-spacing: 1px;
  color: var(--accent);
}

.timer-card {
  background: var(--card);
  border-radius: 16px;
  padding: 32px 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

.mode {
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
  color: var(--muted);
  margin-bottom: 8px;
}

.countdown {
  font-size: 4.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
  margin-bottom: 24px;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
}

.btn {
  font: inherit;
  font-size: 1rem;
  padding: 12px 24px;
  border: 2px solid transparent;
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.96);
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
  font-weight: 600;
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.mode-switch {
  display: flex;
  gap: 8px;
  justify-content: center;
  flex-wrap: wrap;
}

.mode-btn {
  font-size: 0.9rem;
  padding: 8px 16px;
  background: transparent;
  border: 2px solid var(--muted);
  color: var(--muted);
}

.mode-btn:hover {
  border-color: var(--accent);
  color: var(--accent);
  background: transparent;
}

.mode-btn.active {
  border-color: var(--accent);
  color: var(--accent);
  font-weight: 600;
}

.hint {
  margin-top: 20px;
  font-size: 0.9rem;
  color: var(--muted);
}

@media (max-width: 360px) {
  .countdown {
    font-size: 3.5rem;
  }
  .timer-card {
    padding: 24px 16px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.95rem;
  }
}

(function () {
  'use strict';

  const WORK_SECONDS = 25 * 60;
  const BREAK_SECONDS = 5 * 60;

  const countdownEl = document.getElementById('countdown');
  const modeEl = document.getElementById('mode');
  const startPauseBtn = document.getElementById('startPause');
  const resetBtn = document.getElementById('reset');
  const workModeBtn = document.getElementById('workMode');
  const breakModeBtn = document.getElementById('breakMode');

  let remaining = WORK_SECONDS;
  let total = WORK_SECONDS;
  let running = false;
  let intervalId = null;
  let currentMode = 'work'; // 'work' | 'break'

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function render() {
    countdownEl.textContent = formatTime(remaining);
    modeEl.textContent = currentMode === 'work' ? 'Work' : 'Break';
    startPauseBtn.textContent = running ? 'Pause' : 'Start';
    startPauseBtn.setAttribute('aria-label', running ? 'Pause timer' : 'Start timer');
  }

  function tick() {
    if (remaining > 0) {
      remaining -= 1;
      render();
    } else {
      pause();
    }
  }

  function start() {
    if (running) return;
    running = true;
    intervalId = setInterval(tick, 1000);
    render();
  }

  function pause() {
    if (!running) return;
    running = false;
    clearInterval(intervalId);
    intervalId = null;
    render();
  }

  function toggle() {
    if (running) pause();
    else start();
  }

  function reset() {
    pause();
    remaining = total;
    render();
  }

  function setMode(mode) {
    currentMode = mode;
    total = mode === 'work' ? WORK_SECONDS : BREAK_SECONDS;
    remaining = total;
    pause();
    workModeBtn.classList.toggle('active', mode === 'work');
    breakModeBtn.classList.toggle('active', mode === 'break');
    workModeBtn.setAttribute('aria-pressed', mode === 'work');
    breakModeBtn.setAttribute('aria-pressed', mode === 'break');
    render();
  }

  startPauseBtn.addEventListener('click', toggle);
  resetBtn.addEventListener('click', reset);
  workModeBtn.addEventListener('click', function () { setMode('work'); });
  breakModeBtn.addEventListener('click', function () { setMode('break'); });

  document.addEventListener('keydown', function (e) {
    if (e.target.tagName === 'BUTTON') return;
    if (e.code === 'Space') {
      e.preventDefault();
      toggle();
    } else if (e.key === 'r' || e.key === 'R') {
      reset();
    }
  });

  render();
})();
